S = led['scenarios']; A = {a['to'] + '|' + a['from']: a for a in led['attributions']}; L = led['ladder']; D = {r['case']: r for r in led['sensitivities']}
def f(x, nd=3): return f'{x:,.{nd}f}' if abs(x) >= 1e5 else f'{x:.{nd}f}'
def section(n):
    m = re.search(rf'^## {n}\. .*?$', rec, re.M); nxt = re.search(rf'^## {n+1}\. .*?$', rec, re.M)
    return m.start(), (nxt.start() if nxt else len(rec))
def replace(n, body):
    global rec
    a, b = section(n); head = rec[a:].split('\n', 1)[0]
    rec = rec[:a] + head + '\n\n' + body.rstrip('\n') + '\n\n' + rec[b:]
nc, fd, bn, bf, un, uf, orig = (S[k] for k in ('alt-canonical-no-credit', 'alt-canonical-feed100', 'baseline-no-credit', 'baseline-feed100', 'alt-unscaled-no-credit', 'alt-unscaled-feed100', 'original-source-assumed-no-credit'))
