rest = lambda a: a['delta'] - a['by_contribution']['tritium'] - a['by_contribution']['capital'] - a['by_contribution']['om'] - a['by_contribution']['supply']
steps = {s['case']: s for s in L['steps']}; one = {o['case']: o for o in L['one_at_a_time']}; br = L['branch_reads']
L7, L7n = steps['diag-L7-aligned-combined-at-1000'], steps['diag-L7-aligned-combined-at-our-net']
